public class PassByValue {
    public static void main(String[] args) {
        int num = 10;
        System.out.println("Before: " + num);
        modifyPrimitive(num);
        System.out.println("After: " + num);  // Still 10!

        int[] arr = {1, 2, 3};
        System.out.println("Before: " + arr[0]);
        modifyArray(arr);
        System.out.println("After: " + arr[0]);  // Changed to 99!
    }

    public static void modifyPrimitive(int x) {
        x = 100;  // Only modifies local copy
    }

    public static void modifyArray(int[] arr) {
        arr[0] = 99;  // Modifies the actual array through reference
    }
}

public class Car {
    // Fields (instance variables)
    String brand;
    String model;
    int year;
    double fuelLevel;

    // Constructor
    public Car(String brand, String model, int year) {
        this.brand = brand;
        this.model = model;
        this.year = year;
        this.fuelLevel = 100.0;
    }

    // Methods
    public void drive(double distance) {
        double fuelUsed = distance * 0.1;
        if (fuelUsed <= fuelLevel) {
            fuelLevel -= fuelUsed;
            System.out.println("Drove " + distance + " km. Fuel left: " + fuelLevel);
        } else {
            System.out.println("Not enough fuel!");
        }
    }

    public void refuel(double amount) {
        fuelLevel = Math.min(100.0, fuelLevel + amount);
        System.out.println("Refueled. Current level: " + fuelLevel);
    }

    public void displayInfo() {
        System.out.println(year + " " + brand + " " + model);
    }
}

public class CarDemo {
    public static void main(String[] args) {
        // Creating objects with new
        Car car1 = new Car("Toyota", "Corolla", 2023);
        Car car2 = new Car("Honda", "Civic", 2024);

        // Using object methods
        car1.displayInfo();
        car1.drive(50);
        car1.drive(600);  // Not enough fuel
        car1.refuel(30);

        System.out.println();
        car2.displayInfo();
        car2.drive(100);

        // Accessing fields directly
        System.out.println("\nCar1 brand: " + car1.brand);
    }
}

public class Person {
    String name;
    int age;

    public Person(String name, int age) {
        this.name = name;  // this.name = field, name = parameter
        this.age = age;
    }

    public void setName(String name) {
        this.name = name;  // Disambiguates field from parameter
    }

    public Person getOlder() {
        this.age++;        // Optional: this refers to current object
        return this;       // Method chaining: return current object
    }

    public void display() {
        System.out.println(this.name + " is " + this.age);
    }

    public static void main(String[] args) {
        Person p = new Person("Alice", 25);
        p.getOlder().getOlder().display();  // Method chaining
    }
}

public class BankAccount {
    // private: only accessible within this class
    private String accountNumber;
    private double balance;

    // public: accessible from anywhere
    public BankAccount(String accountNumber, double initialBalance) {
        this.accountNumber = accountNumber;
        this.balance = Math.max(0, initialBalance);
    }

    // Getter (accessor)
    public double getBalance() {
        return balance;
    }

    // Getter for account number
    public String getAccountNumber() {
        return accountNumber;
    }

    // Setter with validation
    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            System.out.println("Deposited: " + amount);
        } else {
            System.out.println("Invalid deposit amount");
        }
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            System.out.println("Withdrawn: " + amount);
        } else {
            System.out.println("Insufficient funds or invalid amount");
        }
    }
}

public class BankDemo {
    public static void main(String[] args) {
        BankAccount account = new BankAccount("12345", 1000.0);

        // Cannot access private fields directly!
        // account.balance = 5000; // ERROR!

        System.out.println("Balance: " + account.getBalance());
        account.deposit(500);
        account.withdraw(200);
        System.out.println("Final balance: " + account.getBalance());
    }
}

public class Counter {
    // Instance variable: each object has its own copy
    private int instanceCount;

    // Static variable: shared across all instances
    private static int staticCount = 0;

    public Counter() {
        instanceCount++;
        staticCount++;
    }

    public void showCounts() {
        System.out.println("Instance: " + instanceCount + ", Static: " + staticCount);
    }

    // Static method: belongs to class, not instance
    public static int getTotalCount() {
        return staticCount;
    }

    public static void main(String[] args) {
        Counter c1 = new Counter();
        c1.showCounts();  // Instance: 1, Static: 1

        Counter c2 = new Counter();
        c2.showCounts();  // Instance: 1, Static: 2

        Counter c3 = new Counter();
        c1.showCounts();  // Instance: 1, Static: 3

        // Call static method on class, not instance
        System.out.println("Total: " + Counter.getTotalCount());
    }
}

// Parent class (Superclass)
public class Animal {
    protected String name;
    protected int age;

    public Animal(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public void eat() {
        System.out.println(name + " is eating");
    }

    public void sleep() {
        System.out.println(name + " is sleeping");
    }

    public void makeSound() {
        System.out.println("Some generic animal sound");
    }
}

// Child class (Subclass)
public class Dog extends Animal {
    private String breed;

    public Dog(String name, int age, String breed) {
        super(name, age);  // Call parent constructor
        this.breed = breed;
    }

    @Override
    public void makeSound() {
        System.out.println(name + " says: Woof!");
    }

    public void fetch() {
        System.out.println(name + " is fetching the ball");
    }
}

public class Cat extends Animal {
