        Shape circle = new Circle("red", 5);
        Shape rectangle = new Rectangle("blue", 4, 6);

        System.out.println("Circle area: " + circle.calculateArea());
        System.out.println("Rectangle area: " + rectangle.calculateArea());
    }
}

// Interface: pure abstraction (before Java 8)
public interface Drawable {
    void draw();  // Implicitly public and abstract

    // Default method (Java 8+)
    default void printInfo() {
        System.out.println("This is drawable");
    }

    // Static method (Java 8+)
    static void describe() {
        System.out.println("Drawable objects can be drawn");
    }
}

public interface Resizable {
    void resize(double factor);
}

// A class can implement multiple interfaces
public class Rectangle implements Drawable, Resizable {
    private double width, height;

    public Rectangle(double width, double height) {
        this.width = width;
        this.height = height;
    }

    @Override
    public void draw() {
        System.out.println("Drawing rectangle: " + width + "x" + height);
    }

    @Override
    public void resize(double factor) {
        width *= factor;
        height *= factor;
    }
}

public class InterfaceDemo {
    public static void main(String[] args) {
        Drawable d = new Rectangle(10, 20);
        d.draw();
        d.printInfo();

        Drawable.describe();
    }
}

public class ExceptionDemo {
    public static void main(String[] args) {
        try {
            int result = 10 / 0;
            System.out.println("Result: " + result);
        } catch (ArithmeticException e) {
            System.out.println("Cannot divide by zero: " + e.getMessage());
        }

        // Multiple catch blocks
        try {
            String text = null;
            System.out.println(text.length());
        } catch (NullPointerException e) {
            System.out.println("Null reference!");
        } catch (Exception e) {
            System.out.println("Other error: " + e);
        } finally {
            System.out.println("This always runs");
        }

        // Multi-catch (Java 7+)
        try {
            // Some risky operation
        } catch (NullPointerException | IllegalArgumentException e) {
            System.out.println("Multiple exceptions caught");
        }
    }
}

import java.io.*;

public class CheckedExceptionDemo {
    // Checked exception: must declare or handle
    public static void readFile(String path) throws FileNotFoundException {
        FileReader file = new FileReader(path);  // Checked: IOException hierarchy
    }

    // Using try-with-resources (Java 7+)
    public static void readFileSafe(String path) {
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                System.out.println(line);
            }
        } catch (IOException e) {
