import java.util.concurrent.*;
import java.util.*;

public class ConcurrencyUtils {
    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        Future<Integer> future1 = executor.submit(() -> heavyComputation(5));
        Future<Integer> future2 = executor.submit(() -> heavyComputation(10));
        System.out.println("Future1: " + future1.get());
        System.out.println("Future2: " + future2.get());

        CompletableFuture.supplyAsync(() -> fetchUser(1))
            .thenApply(user -> "Hello, " + user)
            .thenAccept(System.out::println)
            .join();

        ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();
        map.put("key", 1);
        map.computeIfPresent("key", (k, v) -> v + 1);
        System.out.println("Map: " + map.get("key"));

        CountDownLatch latch = new CountDownLatch(3);
        for (int i = 1; i <= 3; i++) {
            final int id = i;
            new Thread(() -> {
                System.out.println("Worker " + id + " done");
                latch.countDown();
            }).start();
        }
        latch.await();
        System.out.println("All workers finished!");
        executor.shutdown();
    }
    static int heavyComputation(int n) {
        try { Thread.sleep(100); } catch (InterruptedException e) {}
        return n * n;
    }
    static String fetchUser(int id) { return "User" + id; }
}

