    private Status status;
    private final LocalDateTime createdAt;
    private LocalDateTime completedAt;

    public Task(int id, String title, String description, Priority priority) {
        this.id = id;
        this.title = title;
        this.description = description;
        this.priority = priority;
        this.status = Status.PENDING;
        this.createdAt = LocalDateTime.now();
    }

    public void complete() {
        this.status = Status.COMPLETED;
        this.completedAt = LocalDateTime.now();
    }

    public int getId() { return id; }
    public String getTitle() { return title; }
    public Priority getPriority() { return priority; }
    public Status getStatus() { return status; }
    public LocalDateTime getCreatedAt() { return createdAt; }

    @Override
    public String toString() {
        return String.format("[%d] %s | %s | %s | Created: %s",
            id, title, priority, status, createdAt);
    }
}

import java.util.*;
import java.util.stream.*;
import java.io.*;
import java.nio.file.*;

public class TaskService {
    private final List<Task> tasks = new ArrayList<>();
    private int nextId = 1;
    private final Path storagePath = Paths.get("tasks.ser");

    public Task addTask(String title, String description, Task.Priority priority) {
        Task task = new Task(nextId++, title, description, priority);
        tasks.add(task);
        saveTasks();
        return task;
    }

    public boolean completeTask(int id) {
        return tasks.stream()
            .filter(t -> t.getId() == id && t.getStatus() != Task.Status.COMPLETED)
            .findFirst()
            .map(t -> { t.complete(); saveTasks(); return true; })
            .orElse(false);
    }

    public boolean deleteTask(int id) {
        boolean removed = tasks.removeIf(t -> t.getId() == id);
        if (removed) saveTasks();
        return removed;
    }

    public List<Task> getAllTasks() { return new ArrayList<>(tasks); }

    public List<Task> getTasksByPriority(Task.Priority priority) {
        return tasks.stream()
            .filter(t -> t.getPriority() == priority)
            .sorted(Comparator.comparing(Task::getCreatedAt).reversed())
            .collect(Collectors.toList());
    }

    public Map<Task.Status, Long> getTaskStatistics() {
        return tasks.stream()
            .collect(Collectors.groupingBy(Task::getStatus, Collectors.counting()));
    }

    @SuppressWarnings("unchecked")
    public void loadTasks() {
        if (!Files.exists(storagePath)) return;
        try (ObjectInputStream ois = new ObjectInputStream(
                new FileInputStream(storagePath.toFile()))) {
            List<Task> loaded = (List<Task>) ois.readObject();
            tasks.clear();
            tasks.addAll(loaded);
            nextId = tasks.stream().mapToInt(Task::getId).max().orElse(0) + 1;
        } catch (Exception e) {
            System.err.println("Failed to load: " + e.getMessage());
        }
    }

    private void saveTasks() {
        try (ObjectOutputStream oos = new ObjectOutputStream(
                new FileOutputStream(storagePath.toFile()))) {
            oos.writeObject(tasks);
        } catch (IOException e) {
            System.err.println("Failed to save: " + e.getMessage());
        }
    }
}

import java.util.*;

public class TaskManager {
    private final TaskService service = new TaskService();
    private final Scanner scanner = new Scanner(System.in);

    public TaskManager() { service.loadTasks(); }

    public void run() {
        System.out.println("=== Java Task Manager ===");
        while (true) {
            printMenu();
            String choice = scanner.nextLine().trim();
            switch (choice) {
                case "1" -> addTask();
                case "2" -> listTasks();
                case "3" -> completeTask();
                case "4" -> deleteTask();
                case "5" -> showStats();
                case "6" -> filterByPriority();
                case "0" -> { System.out.println("Goodbye!"); return; }
                default -> System.out.println("Invalid choice");
            }
        }
    }

    private void printMenu() {
        System.out.println("\n1. Add Task  2. List  3. Complete  4. Delete  5. Stats  6. Filter  0. Exit");
        System.out.print("Choice: ");
    }

    private void addTask() {
        System.out.print("Title: ");
        String title = scanner.nextLine();
        System.out.print("Description: ");
        String desc = scanner.nextLine();
        System.out.print("Priority (LOW/MEDIUM/HIGH): ");
        Task.Priority p = Task.Priority.valueOf(scanner.nextLine().toUpperCase());
        System.out.println("Created: " + service.addTask(title, desc, p));
    }

    private void listTasks() {
        List<Task> tasks = service.getAllTasks();
        if (tasks.isEmpty()) { System.out.println("No tasks"); return; }
        tasks.forEach(System.out::println);
    }

    private void completeTask() {
        System.out.print("Task ID: ");
        System.out.println(service.completeTask(Integer.parseInt(scanner.nextLine())) ? "Done!" : "Not found");
    }

    private void deleteTask() {
        System.out.print("Task ID: ");
        System.out.println(service.deleteTask(Integer.parseInt(scanner.nextLine())) ? "Deleted!" : "Not found");
    }

    private void showStats() {
        service.getTaskStatistics().forEach((s, c) -> System.out.println(s + ": " + c));
    }

    private void filterByPriority() {
        System.out.print("Priority: ");
        Task.Priority p = Task.Priority.valueOf(scanner.nextLine().toUpperCase());
        service.getTasksByPriority(p).forEach(System.out::println);
    }

    public static void main(String[] args) { new TaskManager().run(); }
}

