import java.util.*;

// Subject
interface NewsAgency {
    void register(Observer observer);
    void unregister(Observer observer);
    void notifyObservers(String news);
}

// Observer
interface Observer {
    void update(String news);
}

class BBCNews implements NewsAgency {
    private final List<Observer> observers = new ArrayList<>();

    public void register(Observer o) { observers.add(o); }
    public void unregister(Observer o) { observers.remove(o); }

    public void notifyObservers(String news) {
        for (Observer o : observers) {
            o.update(news);
        }
    }

    public void publishNews(String news) {
        System.out.println("BBC Publishing: " + news);
        notifyObservers(news);
    }
}

class NewsChannel implements Observer {
    private final String name;

    NewsChannel(String name) { this.name = name; }

    public void update(String news) {
        System.out.println(name + " received: " + news);
    }
}

public class ObserverDemo {
    public static void main(String[] args) {
        BBCNews bbc = new BBCNews();

        NewsChannel cnn = new NewsChannel("CNN");
        NewsChannel fox = new NewsChannel("Fox News");
        NewsChannel aljazeera = new NewsChannel("Al Jazeera");

        bbc.register(cnn);
        bbc.register(fox);
        bbc.register(aljazeera);

        bbc.publishNews("Breaking: Java 25 released!");

        bbc.unregister(fox);
        System.out.println("\nAfter Fox unsubscribed:");
        bbc.publishNews("Markets hit record high");
    }
}

