// Sealed class: only permits listed subclasses
public abstract sealed class Shape
    permits Circle, Rectangle, Triangle {}

public final class Circle extends Shape {
    private final double radius;
    public Circle(double radius) { this.radius = radius; }
    public double area() { return Math.PI * radius * radius; }
}

public final class Rectangle extends Shape {
    private final double width, height;
    public Rectangle(double w, double h) { this.width = w; this.height = h; }
    public double area() { return width * height; }
}

public non-sealed class Triangle extends Shape {
    // Can be extended further (non-sealed)
    public double area() { return 0; }
}

// Exhaustive pattern matching with switch (Java 21)
public class SealedDemo {
    public static void main(String[] args) {
        Shape shape = new Circle(5);

        // Compiler knows all possible subtypes — no default needed!
        String description = switch (shape) {
            case Circle c -> "Circle with radius " + c.area();
            case Rectangle r -> "Rectangle with area " + r.area();
            case Triangle t -> "Triangle";
        };

        System.out.println(description);
    }
}

import java.util.concurrent.*;
import java.util.stream.*;

public class VirtualThreads {
    public static void main(String[] args) throws Exception {
        // Traditional platform threads (expensive, limited to ~10K)
        System.out.println("=== Platform Threads ===");
        long start = System.currentTimeMillis();
        try (var executor = Executors.newFixedThreadPool(100)) {
            IntStream.range(0, 10_000).forEach(i ->
                executor.submit(() -> {
                    Thread.sleep(10);
                    return i;
                })
            );
        }
        System.out.println("Platform threads took: " + (System.currentTimeMillis() - start) + "ms");

        // Virtual threads (lightweight, millions possible)
        System.out.println("\n=== Virtual Threads ===");
        start = System.currentTimeMillis();
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10_000).forEach(i ->
                executor.submit(() -> {
                    Thread.sleep(10);
                    return i;
                })
            );
        }
        System.out.println("Virtual threads took: " + (System.currentTimeMillis() - start) + "ms");

        // Virtual thread with Thread.startVirtualThread (Java 21)
        Thread.startVirtualThread(() -> {
            System.out.println("Running on virtual thread: " + Thread.currentThread());
        });

        Thread.sleep(100);  // Let virtual thread finish
    }
}

public class PatternMatching {
    public static void main(String[] args) {
        System.out.println(formatter(42));
        System.out.println(formatter("hello"));
        System.out.println(formatter(3.14));
        System.out.println(formatter(null));
        System.out.println(formatter(new int[]{1, 2, 3}));
    }

    static String formatter(Object obj) {
        return switch (obj) {
            case Integer i -> "Integer: " + i;
            case String s -> "String: " + s.toUpperCase();
            case Double d -> "Double: " + String.format("%.2f", d);
            case null -> "null value";
            case int[] arr -> "Array of length " + arr.length;
            default -> "Unknown type: " + obj.getClass().getSimpleName();
        };
    }
}

