import java.lang.reflect.*;
import java.util.Arrays;

public class ReflectionBasics {
    public static void main(String[] args) throws Exception {
        // Three ways to get Class object
        Class<?> clazz1 = String.class;
        Class<?> clazz2 = "hello".getClass();
        Class<?> clazz3 = Class.forName("java.lang.String");

        System.out.println("Class: " + clazz1.getName());
        System.out.println("Simple: " + clazz1.getSimpleName());
        System.out.println("Package: " + clazz1.getPackageName());
        System.out.println("Is primitive? " + clazz1.isPrimitive());

        // Inspect methods
        System.out.println("\nMethods:");
        Method[] methods = clazz1.getDeclaredMethods();
        Arrays.stream(methods)
            .limit(5)
            .forEach(m -> System.out.println("  " + m.getName() + " - " + Arrays.toString(m.getParameterTypes())));

        // Inspect fields
        Class<?> personClass = Class.forName("Person");
        Field[] fields = personClass.getDeclaredFields();
        System.out.println("\nPerson fields:");
        for (Field f : fields) {
            System.out.println("  " + f.getType().getSimpleName() + " " + f.getName());
        }
    }
}

