    }
}

import java.lang.reflect.*;

public class ReflectionInvocation {
    public static void main(String[] args) throws Exception {
        Class<?> clazz = Class.forName("Person");

        // Create instance using no-arg constructor
        Person p1 = (Person) clazz.getDeclaredConstructor().newInstance();

        // Create instance with arguments
        Constructor<?> ctor = clazz.getDeclaredConstructor(String.class, int.class);
        Person p2 = (Person) ctor.newInstance("Alice", 30);

        // Access private field
        Field nameField = clazz.getDeclaredField("name");
        nameField.setAccessible(true);  // Bypass private access
        nameField.set(p1, "Bob");

        // Invoke private method
        Method greetMethod = clazz.getDeclaredMethod("greet");
        greetMethod.setAccessible(true);
        greetMethod.invoke(p1);  // Hello, I'm Bob
        greetMethod.invoke(p2);  // Hello, I'm Alice

        // Get field value
        Field ageField = clazz.getDeclaredField("age");
        ageField.setAccessible(true);
        System.out.println("Age: " + ageField.get(p2));
    }
}

import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

// Define annotation
@Retention(RetentionPolicy.RUNTIME)
@Target({ElementType.TYPE, ElementType.METHOD})
public @interface Route {
    String value();
    String method() default "GET";
}

// Apply annotation
@Route("/users")
class UserController {
    @Route("/users", method = "GET")
    public List<String> getAll() {
        return List.of("Alice", "Bob");
    }

    @Route("/users", method = "POST")
    public String create(String name) {
        return "Created: " + name;
    }
}

// Process annotations (mini framework)
public class Router {
    public static void main(String[] args) {
        scanRoutes(UserController.class);
    }

    static void scanRoutes(Class<?> controller) {
        // Class-level annotation
        Route baseRoute = controller.getAnnotation(Route.class);
        String basePath = baseRoute != null ? baseRoute.value() : "";

        System.out.println("Controller: " + basePath);

        // Method-level annotations
        for (Method m : controller.getDeclaredMethods()) {
            Route route = m.getAnnotation(Route.class);
            if (route != null) {
                System.out.println("  " + route.method() + " " + basePath + route.value() +
                    " -> " + m.getName() + "()");
            }
        }
    }
}

