import java.util.regex.*;

public class InputValidation {
    // OWASP: Never trust user input
    private static final Pattern SAFE_USERNAME = Pattern.compile("^[a-zA-Z0-9_]{3,20}$");
    private static final Pattern SAFE_EMAIL = Pattern.compile("^[A-Za-z0-9+_.-]+@(.+)$");

    public static boolean isValidUsername(String username) {
        return username != null && SAFE_USERNAME.matcher(username).matches();
    }

    public static boolean isValidEmail(String email) {
        return email != null && SAFE_EMAIL.matcher(email).matches();
    }

    // Prevent path traversal
    public static boolean isSafePath(String userPath) {
        if (userPath == null || userPath.isEmpty()) return false;
        // Reject paths containing .. or null bytes
        return !userPath.contains("..") && !userPath.contains("\0");
    }

    // Prevent command injection
    public static boolean isSafeCommand(String input) {
        String[] dangerous = {";", "&", "|", "$", "`", ">", "<", "\"", "\'"};
        for (String d : dangerous) {
            if (input.contains(d)) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println("Valid user: " + isValidUsername("alice_99"));
        System.out.println("Invalid user: " + isValidUsername("alice<script>"));
        System.out.println("Safe path: " + isSafePath("data/file.txt"));
        System.out.println("Unsafe path: " + isSafePath("../../etc/passwd"));
    }
}

import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;
import java.util.Base64;

public class CryptoDemo {
    // NEVER hardcode keys in production — use KeyStore or environment variables
    private static final String ALGORITHM = "AES";
    private static final String TRANSFORMATION = "AES/GCM/NoPadding";

    // Hash password with salt (use BCrypt/Argon2 in production)
    public static String hashPassword(String password, byte[] salt) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(salt);
        byte[] hash = md.digest(password.getBytes());
        return Base64.getEncoder().encodeToString(hash);
    }

    // Encrypt with AES-GCM (authenticated encryption)
    public static String encrypt(String plaintext, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        byte[] iv = new byte[12];  // 96-bit IV for GCM
        new SecureRandom().nextBytes(iv);
        GCMParameterSpec spec = new GCMParameterSpec(128, iv);
        cipher.init(Cipher.ENCRYPT_MODE, key, spec);
        byte[] encrypted = cipher.doFinal(plaintext.getBytes());
        // Prepend IV to ciphertext for decryption
        byte[] combined = new byte[iv.length + encrypted.length];
        System.arraycopy(iv, 0, combined, 0, iv.length);
        System.arraycopy(encrypted, 0, combined, iv.length, encrypted.length);
        return Base64.getEncoder().encodeToString(combined);
    }

    public static String decrypt(String ciphertext, SecretKey key) throws Exception {
        byte[] combined = Base64.getDecoder().decode(ciphertext);
        byte[] iv = new byte[12];
        byte[] encrypted = new byte[combined.length - 12];
        System.arraycopy(combined, 0, iv, 0, 12);
        System.arraycopy(combined, 12, encrypted, 0, encrypted.length);

        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        GCMParameterSpec spec = new GCMParameterSpec(128, iv);
        cipher.init(Cipher.DECRYPT_MODE, key, spec);
        return new String(cipher.doFinal(encrypted));
    }

    public static void main(String[] args) throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance(ALGORITHM);
        keyGen.init(256);
        SecretKey key = keyGen.generateKey();

        String message = "Secret data";
        String encrypted = encrypt(message, key);
        String decrypted = decrypt(encrypted, key);

        System.out.println("Original: " + message);
        System.out.println("Encrypted: " + encrypted);
        System.out.println("Decrypted: " + decrypted);

        // Password hashing
        byte[] salt = new byte[16];
        new SecureRandom().nextBytes(salt);
        String hash = hashPassword("mypassword", salt);
        System.out.println("Password hash: " + hash);
    }
}

import java.io.*;
import java.util.*;

public class SecureDeserialization {
    // Whitelist of allowed classes for deserialization
    private static final Set<String> ALLOWED_CLASSES = Set.of(
        "com.example.User",
        "com.example.Order"
    );

    public static Object safeDeserialize(byte[] data) throws Exception {
        try (ObjectInputStream ois = new ObjectInputStream(
                new ByteArrayInputStream(data)) {
            @Override
            protected Class<?> resolveClass(ObjectStreamClass desc) {
                String className = desc.getName();
                if (!ALLOWED_CLASSES.contains(className)) {
                    throw new SecurityException("Class not allowed: " + className);
                }
                try {
                    return Class.forName(className);
                } catch (ClassNotFoundException e) {
                    throw new IOException("Class not found: " + className, e);
                }
            }
        }) {
            return ois.readObject();
        }
    }

    // Better: Use JSON instead of Java serialization
    // Jackson: ObjectMapper mapper = new ObjectMapper();
    // User user = mapper.readValue(json, User.class);
}

import java.util.*;
import java.util.stream.*;

public class PerformancePitfalls {
    public static void main(String[] args) {
        // PITFALL 1: String concatenation in loops
        long start = System.currentTimeMillis();
        String bad = "";
        for (int i = 0; i < 100000; i++) {
            bad += i;  // Creates new String each iteration!
        }
        System.out.println("String concat: " + (System.currentTimeMillis() - start) + "ms");

        start = System.currentTimeMillis();
        StringBuilder good = new StringBuilder();
        for (int i = 0; i < 100000; i++) {
            good.append(i);
        }
        System.out.println("StringBuilder: " + (System.currentTimeMillis() - start) + "ms");

        // PITFALL 2: Autoboxing in tight loops
        start = System.currentTimeMillis();
        Long sumBad = 0L;
        for (long i = 0; i < 10_000_000; i++) {
            sumBad += i;  // Autoboxing every iteration!
        }
        System.out.println("Autoboxed sum: " + (System.currentTimeMillis() - start) + "ms");

        start = System.currentTimeMillis();
        long sumGood = 0L;
        for (long i = 0; i < 10_000_000; i++) {
            sumGood += i;
        }
        System.out.println("Primitive sum: " + (System.currentTimeMillis() - start) + "ms");

        // PITFALL 3: Inefficient collection initialization
        List<String> list = new ArrayList<>(10000);  // Pre-size if known

        // PITFALL 4: Substring memory leak (fixed in Java 7u6+)
        // Old: new String(hugeCharArray, start, end) shared the array
        // Now: substring creates a new char[] copy

        // GOOD: Stream pipeline fusion
        List<Integer> result = IntStream.range(0, 1_000_000)
            .filter(n -> n % 2 == 0)
            .map(n -> n * 2)
            .boxed()
            .collect(ArrayList::new, ArrayList::add, ArrayList::addAll);
        System.out.println("Stream result size: " + result.size());
    }
}

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.runner.*;
import org.openjdk.jmh.runner.options.*;
import java.util.concurrent.TimeUnit;

// JMH (Java Microbenchmark Harness) — the correct way to benchmark
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@State(Scope.Thread)
@Warmup(iterations = 3)
@Measurement(iterations = 5)
public class StringBenchmark {
    private String text = "Hello, World!";

    @Benchmark
    public String stringConcat() {
        return "Prefix: " + text + " :Suffix";
    }

    @Benchmark
    public String stringBuilder() {
        return new StringBuilder().append("Prefix: ")
            .append(text).append(" :Suffix").toString();
    }

    @Benchmark
    public String stringFormat() {
        return String.format("Prefix: %s :Suffix", text);
    }

    public static void main(String[] args) throws Exception {
        Options opt = new OptionsBuilder()
            .include(StringBenchmark.class.getSimpleName())
            .forks(1)
            .build();
        new Runner(opt).run();
    }
}

