import io.micrometer.core.instrument.*;
import org.springframework.stereotype.Component;

@Component
public class OrderMetrics {
    private final Counter orderCounter;
    private final Timer orderTimer;
    private final Gauge stockGauge;

    public OrderMetrics(MeterRegistry registry) {
        this.orderCounter = Counter.builder("orders.created")
            .description("Total orders created")
            .register(registry);

        this.orderTimer = Timer.builder("orders.processing.time")
            .description("Order processing time")
            .register(registry);

        this.stockGauge = Gauge.builder("inventory.stock", this, OrderMetrics::getStockLevel)
            .description("Current stock level")
            .register(registry);
    }

    public void recordOrder() {
        orderCounter.increment();
    }

    public void recordProcessingTime(Runnable orderProcessing) {
        orderTimer.record(orderProcessing);
    }

    private double getStockLevel() {
        return 150.0;  // Fetch from actual inventory
    }
}

