import javafx.beans.property.*;
import javafx.beans.binding.*;

public class DataBinding {
    public static void main(String[] args) {
        // Simple properties
        StringProperty name = new SimpleStringProperty("Alice");
        IntegerProperty age = new SimpleIntegerProperty(25);

        // Bind label text to property
        Label nameLabel = new Label();
        nameLabel.textProperty().bind(name);

        // Computed binding
        StringProperty greeting = new SimpleStringProperty();
        greeting.bind(Bindings.concat("Hello, ", name, "! Age: ", age));

        System.out.println(greeting.get());  // Hello, Alice! Age: 25

        // Bidirectional binding
        StringProperty field1 = new SimpleStringProperty();
        StringProperty field2 = new SimpleStringProperty();
        field1.bindBidirectional(field2);

        field1.set("test");
        System.out.println(field2.get());  // test

        // Observable collections
        ObservableList<String> items = FXCollections.observableArrayList();
        items.addListener((ListChangeListener<String>) change -> {
            while (change.next()) {
                if (change.wasAdded()) {
                    System.out.println("Added: " + change.getAddedSubList());
                }
            }
        });
        items.add("Item 1");  // Prints: Added: [Item 1]
    }
}

