import org.apache.kafka.clients.producer.*;
import org.apache.kafka.clients.consumer.*;
import java.time.Duration;
import java.util.*;

public class KafkaDemo {
    // Producer: send events
    public static void produce() {
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("acks", "all");  // Wait for all replicas

        try (Producer<String, String> producer = new KafkaProducer<>(props)) {
            for (int i = 0; i < 10; i++) {
                ProducerRecord<String, String> record = new ProducerRecord<>(
                    "orders", "order-" + i, "Order payload " + i
                );
                producer.send(record, (metadata, exception) -> {
                    if (exception == null) {
                        System.out.printf("Sent to %s-%d offset %d%n",
                            metadata.topic(), metadata.partition(), metadata.offset());
                    }
                });
            }
        }
    }

    // Consumer: read events
    public static void consume() {
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("group.id", "order-processor");
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");

        try (Consumer<String, String> consumer = new KafkaConsumer<>(props)) {
            consumer.subscribe(List.of("orders"));

            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
                for (ConsumerRecord<String, String> record : records) {
                    System.out.printf("Received: %s = %s [partition=%d]%n",
                        record.key(), record.value(), record.partition());
                }
            }
        }
    }

    public static void main(String[] args) {
        new Thread(KafkaDemo::produce).start();
        KafkaDemo.consume();
    }
}

import org.apache.spark.sql.*;
import static org.apache.spark.sql.functions.*;

public class SparkDemo {
    public static void main(String[] args) {
        SparkSession spark = SparkSession.builder()
            .appName("JavaSparkDemo")
            .master("local[*]")  // Use all CPU cores locally
            .getOrCreate();

        // Read JSON data
        Dataset<Row> df = spark.read().json("data/users.json");

        // Show schema and sample data
        df.printSchema();
        df.show(5);

        // Transformations (lazy)
        Dataset<Row> adults = df.filter(col("age").geq(18))
            .select("name", "age", "city")
            .orderBy(desc("age"));

        // Aggregations
        Dataset<Row> cityCounts = df.groupBy("city")
            .agg(count("*").alias("count"), avg("age").alias("avg_age"))
            .orderBy(desc("count"));

        // Actions (trigger execution)
        adults.show();
        cityCounts.show();

        // SQL interface
        df.createOrReplaceTempView("users");
        spark.sql("SELECT city, COUNT(*) as cnt FROM users GROUP BY city ORDER BY cnt DESC").show();

        spark.stop();
    }
}

import reactor.core.publisher.*;
import reactor.core.scheduler.Schedulers;
import java.time.Duration;

public class ReactorDemo {
    public static void main(String[] args) throws InterruptedException {
        // Mono: 0 or 1 element
        Mono<String> mono = Mono.just("Hello");
        mono.subscribe(System.out::println);

        // Flux: 0 to N elements
        Flux<Integer> flux = Flux.range(1, 5);
        flux.map(n -> n * n)
            .filter(n -> n > 5)
            .subscribe(n -> System.out.println("Flux: " + n));

        // Async processing with backpressure
        Flux.interval(Duration.ofMillis(100))
            .take(10)
            .map(i -> "Tick " + i)
            .subscribeOn(Schedulers.boundedElastic())
            .subscribe(System.out::println);

        // Error handling
        Flux.just(1, 2, 0, 4)
            .map(i -> 10 / i)
            .onErrorResume(e -> Flux.just(-1))
            .subscribe(System.out::println);

        Thread.sleep(2000);  // Wait for async operations
    }
}
